//IMG:/Users/dioscorid/Projects/C/presets/textures/Images/15.png
// =========================================================================
// Title: Squished Image
// Based on: "Squished Coordinates" by pyBlob
//           https://www.shadertoy.com/view/W3KcWd
//
// License: Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported
//          (CC BY-NC-SA 3.0) - https://creativecommons.org/licenses/by-nc-sa/3.0/
//
// Note: Adapted and modified for the "Surfaces Explorer" engine.
//       Solo la DEFORMAZIONE dell'originale: niente assi rossi, niente
//       cerchio arancione, niente velo bianco. L'immagine resta a piena
//       saturazione e viene solo animata.
// =========================================================================
//
// COSA FA: la coordinata viene schiacciata lungo un asse e stirata lungo
// quello perpendicolare. La matrice ha determinante 1, quindi l'area si
// conserva: l'immagine si deforma senza gonfiarsi ne' restringersi.
// L'asse ruota nel tempo e l'immagine sembra ondeggiare.
//
// DUE VINCOLI DEL RAMO SHADERTOY, entrambi gia' costati un errore:
//  1. gli slider A..F e t NON sono usabili qui: il motore li dichiara come
//     variabili LOCALI di getCustomColor(), mentre mainImage() e' una
//     funzione a se' -> "'A' : undeclared identifier";
//  2. niente dichiarazioni a livello di MODULO (const, variabili globali):
//     con due mesh che usano questo script il file ne conterrebbe due copie
//     -> "'SQUISH' : redefinition". Il motore rinomina per-mesh solo i
//     simboli noti (iTime, mainImage, iChannelN...), non i nomi dell'utente.
// Percio' i parametri stanno DENTRO mainImage: li' lo scope e' per-funzione
// e ogni mesh ha la sua copia.

void mainImage(out vec4 Q, vec2 U)
{
    // --- PARAMETRI (modificabili qui) ---
    float squish = 0.35;   // quanto schiaccia (0 = immagine ferma e intatta)
    float speed  = 0.2;    // velocita' di rotazione dell'asse

    // Coordinata centrata: nel ramo Shadertoy iResolution vale 1024,
    // quindi V va circa in [-0.5, 0.5].
    vec2 V = U / iResolution.xy - 0.5;

    float a = iTime * speed;   // angolo dell'asse di deformazione

    // Deformazione a determinante 1: exp(-e) su un asse, exp(+e) sull'altro.
    // E' la stessa matrice dell'originale, scritta per esteso.
    float c2 = cos(a) * cos(a);
    float s2 = sin(a) * sin(a);
    float sh = -sin(2.0 * a) * sinh(squish);
    V = mat2(c2 * exp(-squish) + s2 * exp(squish), sh,
             sh, c2 * exp(squish) + s2 * exp(-squish)) * V;

    // Campionamento diretto, senza bias di mip: l'immagine resta nitida.
    // +0.5 riporta la coordinata in [0,1].
    Q = texture(iChannel0, V + 0.5);
}
